  "SVT (Coeff 6) \u2022 Physique-Chimie (Coeff 6) \u2022 Math\u00e9matiques (Coeff 5)": { en: "Natural Sciences (Coeff 6) \u2022 Physics & Chemistry (Coeff 6) \u2022 Mathematics (Coeff 5)", ar: "\u0639\u0644\u0648\u0645 \u0627\u0644\u0637\u0628\u064a\u0639\u0629 \u0648\u0627\u0644\u062d\u064a\u0627\u0629 (\u0645\u0639\u0627\u0645\u0644 6) \u2022 \u0627\u0644\u0639\u0644\u0648\u0645 \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0626\u064a\u0629 (\u0645\u0639\u0627\u0645\u0644 6) \u2022 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a (\u0645\u0639\u0627\u0645\u0644 5)" },
  "Choisir cette fili\u00e8re": { en: "Choose this stream", ar: "\u0627\u0628\u062f\u0623 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0628\u0647\u0630\u0647 \u0627\u0644\u0634\u0639\u0628\u0629" },
  "Math\u00e9matiques (Coeff 7) \u2022 Physique-Chimie (Coeff 6) \u2022 SVT (Coeff 2)": { en: "Mathematics (Coeff 7) \u2022 Physics & Chemistry (Coeff 6) \u2022 Natural Sciences (Coeff 2)", ar: "\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a (\u0645\u0639\u0627\u0645\u0644 7) \u2022 \u0627\u0644\u0639\u0644\u0648\u0645 \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0626\u064a\u0629 (\u0645\u0639\u0627\u0645\u0644 6) \u2022 \u0639\u0644\u0648\u0645 \u0627\u0644\u0637\u0628\u064a\u0639\u0629 \u0648\u0627\u0644\u062d\u064a\u0627\u0629 (\u0645\u0639\u0627\u0645\u0644 2)" },
  "Contenu Essentiel": { en: "Core Educational Content", ar: "\u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a \u0627\u0644\u0623\u0633\u0627\u0633\u064a" },
  "Les 4 Piliers de EOS BAC": { en: "The 4 Pillars of EOS BAC", ar: "\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0645\u0646\u0635\u0629 \u0627\u0644\u0623\u0631\u0628\u0639\u0629" },
  "Tout ce dont tu as besoin r\u00e9uni en 4 cat\u00e9gories fondamentales.": { en: "Everything you need gathered into 4 fundamental categories.", ar: "\u0643\u0644 \u0645\u0627 \u062a\u062d\u062a\u0627\u062c\u0647 \u0644\u0644\u062a\u062d\u0636\u064a\u0631 \u0645\u062a\u0648\u0641\u0631 \u0641\u064a \u0623\u0631\u0628\u0639\u0629 \u0623\u0642\u0633\u0627\u0645 \u0648\u0627\u0636\u062d\u0629 \u0648\u0633\u0647\u0644\u0629 \u0627\u0644\u0648\u0635\u0648\u0644." },
  "Pourquoi choisir EOS BAC ?": { en: "Why choose EOS BAC?", ar: "\u0644\u0645\u0627\u0630\u0627 EOS BAC\u061f" },
  "Con\u00e7ue pour \u00eatre ton espace de r\u00e9vision quotidien jusqu\u2019au jour du BAC.": { en: "Designed to be your daily revision space until the day of the BAC.", ar: "\u0635\u064f\u0645\u0645\u062a \u0627\u0644\u0645\u0646\u0635\u0629 \u0644\u062a\u0643\u0648\u0646 \u0631\u0641\u064a\u0642\u0643 \u0627\u0644\u064a\u0648\u0645\u064a \u0641\u064a \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u062d\u062a\u0649 \u064a\u0648\u0645 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646." },
  "Pr\u00eat \u00e0 commencer tes r\u00e9visions ?": { en: "Ready to start studying?", ar: "\u062c\u0627\u0647\u0632 \u062a\u0628\u062f\u0623 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629\u061f" },
  "Acc\u00e8de gratuitement \u00e0 toutes les ressources et commence \u00e0 pr\u00e9parer ton BAC avec rigueur.": { en: "Access all resources for free and start preparing for your BAC with confidence.", ar: "\u0627\u0646\u0636\u0645 \u0627\u0644\u0622\u0646 \u0645\u062c\u0627\u0646\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0641\u064a \u0645\u0631\u0627\u062c\u0639\u0629 \u062f\u0631\u0648\u0633\u0643 \u0648\u0627\u0644\u062a\u062d\u0636\u064a\u0631 \u0644\u0644\u0628\u0643\u0627\u0644\u0648\u0631\u064a\u0627 \u0628\u062b\u0642\u0629 \u0648\u062a\u0646\u0638\u064a\u0645." },
  "Commencer gratuitement": { en: "Start for free", ar: "\u0627\u0628\u062f\u0623 \u0627\u0644\u0622\u0646 \u0645\u062c\u0627\u0646\u064b\u0627" },
